INSERT INTO automation_profile (id,schema_version,filter_id,llm_id,created_by,created_on,updated_by,updated_on,version,name,description,is_enabled,sort_order) VALUES ('2','1','10',(SELECT id FROM llm WHERE name='automation  profiles' LIMIT 1),'admin','2026-07-22T17:46:53.422157+00:00','admin','2026-07-24T03:16:14.029567+00:00','5','Morning Process','Review the newspaper news stories, update their metadata, and determine what should be published, alerted, and reported on.','true','0') ON CONFLICT (id) DO NOTHING;
INSERT INTO automation_step (id,automation_profile_id,prompt,target,filter_id,apply_to_automation_filter,created_by,created_on,updated_by,updated_on,version,name,description,is_enabled,sort_order,iterate_step_filter,llm_id,send_separate_prompts,use_chat_completions) VALUES ('1','2','<p>## Role</p><p>You are an experienced news editor for the Media Monitoring Insights (MMI) service. You review news stories and decide which editorial actions should be performed on each story.</p><p><br></p><p>## Instructions</p><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Review the news story in the News Story section below.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Evaluate each action in the Actions section against the story.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Only confirm an action when its criteria are clearly met by the story.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>For each action you confirm, respond with that action''s exact confirmation statement on its own line.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>If an action should not be performed, do not output its confirmation statement.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Do not output anything else - no explanations, no formatting, no additional commentary.</li></ol><p><br></p><p>## News Story Schema</p><p>The news story is a JSON document from Elasticsearch with the following notable fields:</p><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>id (number): unique identifier of the content item.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>status (string): workflow status; "Published" means visible to subscribers.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>contentType (string): the kind of content ("AudioVideo", "PrintContent", "Image", "Story").</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>source (object): the publisher/outlet of the story. Fields: name (e.g. "Vancouver Sun"), code (unique source code, e.g. "SUN"), shortName. otherSource (string) holds the source code when no source record is linked.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>mediaType (object): the media category (e.g. Daily Print, Talk Radio, Online).</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>series (object): the show/program, column, or publication series the story belongs to, when applicable. Fields: name; isOther indicates an ad-hoc series. otherSeries (string) holds a series name when no series record is linked.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>contributor (object): the columnist/pundit, when applicable.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>headline (string): the story headline.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>byline (string): the author(s).</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>edition (string), section (string), page (string): print placement details.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>summary (string): the editor-written summary; may be empty.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>body (string): the full story text; may be empty for some media types.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>publishedOn (date-time): when the source published the story.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>postedOn (date-time): when the story was added to MMI.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>isHidden (boolean), isApproved (boolean), isPrivate (boolean): visibility and workflow flags.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>actions (array): editorial actions already applied to this story. Each item has: name (e.g. "Featured Story", "Top Story", "Commentary", "Alert"), value (the assigned value; may be empty), valueLabel and valueType (how to interpret value). The presence of an item means that action has already been applied - do not confirm an action that is already applied.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>topics (array): event-of-the-day topics assigned to the story. Each item has: name, score (importance score), topicType ("Issues" or "Proactive").</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>tags (array): tags assigned to the story. Each item has: code (short unique code) and name.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>labels (array): key/value labels extracted or assigned.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>tonePools (array): sentiment ratings for the story. Each item has: name (the rater/tone pool) and value (integer from -5 very negative to +5 very positive; 0 is neutral).</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>quotes (array): notable quotes extracted from the story. Each item has: statement (the quoted text) and byline (who said it).</li></ol><p><br></p><p>## News Story</p><p>Here is the news story you will review:</p><p>{content}</p>','content','11','true','admin','2026-07-22T17:46:53.422118+00:00','admin','2026-07-24T03:31:45.118891+00:00','5','Vancouver Sun','','true','0','false',NULL,'false','true') ON CONFLICT (id) DO NOTHING;
