INSERT INTO automation_action (id,name,automation_step_id,prompt,action_type,max_calls,confirmation_statement,content_field,content_action_id,is_enabled,sort_order,created_by,created_on,updated_by,updated_on,version,objective,report_id,notification_id,prior_action_id,auto_execute,llm_id,abort_if_no_confirmation,works_on,create_identifier,create_clone,settings) VALUES ('622','Top Story Notifications','5','<p>Respond with "[RUN NOTIFICATION]".</p>','run-notification',NULL,'[RUN NOTIFICATION]',NULL,NULL,'false','4','admin','2026-07-23T20:50:58.970677+00:00','admin','2026-07-24T00:01:33.573932+00:00','1',NULL,NULL,(SELECT id FROM notification WHERE id='1'),NULL,'true',NULL,'false',NULL,NULL,'false','{}') ON CONFLICT (id) DO NOTHING;
