  -- Advance identity sequences past the seeded ids so future inserts don't collide.
  PERFORM setval(pg_get_serial_sequence('filter', 'id'), GREATEST((SELECT max(id) FROM filter), 1));
  PERFORM setval(pg_get_serial_sequence('automation_profile', 'id'), GREATEST((SELECT max(id) FROM automation_profile), 1));
  PERFORM setval(pg_get_serial_sequence('automation_step', 'id'), GREATEST((SELECT max(id) FROM automation_step), 1));
  PERFORM setval(pg_get_serial_sequence('automation_action', 'id'), GREATEST((SELECT max(id) FROM automation_action), 1));

